const exactName = (value: string) => value.trim().replaceAll('（', '(').replaceAll('）', ')');
const sameIdentity = (row: {schoolName: string; campusName: string | null}, school: string, campus: string | null) =>
  exactName(row.schoolName) === exactName(school) &&
  (row.campusName !== null
    ? campus !== null && exactName(row.campusName) === exactName(campus)
    : campus === null || exactName(campus) === exactName(row.schoolName));

/** The schema is checked here so its release marker remains in the live bundle. */
export function getSchoolAdmissions2026(schoolName: string, campusName: string | null, provinceAdcode: string): readonly SchoolAdmission2026[] {
  if (schoolAdmissions2026Metadata.schemaVersion !== schoolAdmissionsSchema) return [];
  return schoolAdmissions2026.filter(row => row.year === 2026 &&
    row.provinceAdcode === provinceAdcode && sameIdentity(row, schoolName, campusName));
}

export function getSchoolAdmissionQueryLink2026(schoolName: string, campusName: string | null, provinceAdcode?: string): SchoolAdmissionQueryLink2026 | null {
  if (provinceAdcode) {
    const record = getSchoolAdmissions2026(schoolName, campusName, provinceAdcode)[0];
    if (record) return {url: record.sourceUrl, title: record.sourceTitle};
  }
  const link = schoolAdmissionQueryLinks2026.find(row => sameIdentity(row, schoolName, campusName));
  if (link) return {url: link.url, title: link.title};
  if (provinceAdcode === '330000') return {url: 'https://www.zjzs.net/art/2026/7/21/art_45_12550.html', title: '浙江省考试院2026专业投档表'};
  return null;
}
